function renderProgressSignals(){const box=$('progressCards');box.replaceChildren();const rows=data.exercises.filter(e=>e.history.length>=2).sort((a,b)=>b.sessions-a.sessions).slice(0,9);if(!rows.length)text(box,'p','Log at least two sessions of an exercise to compare progress.');rows.forEach(e=>{const first=e.history[0],latest=e.history.at(-1),card=text(box,'div','','progresscard');text(card,'small',e.name);text(card,'p',first.date+' → '+latest.date);[['weight','Best weight','kg'],['reps','Total reps',''],['volume','Session volume','kg']].forEach(([key,label,unit])=>{const a=first[key]||0,b=latest[key]||0,delta=b-a,line=text(card,'div','','signalrow');text(line,'span',label);text(line,'strong',num(a)+' → '+num(b)+' '+unit);const change=a?num(delta/a*100)+'%':delta>0?'New baseline':'Unchanged';text(line,'span',(delta>0?'↑ +':delta<0?'↓ ':'→ ')+change,'trend '+(delta>0?'up':delta<0?'down':'flat'))});text(card,'p','Session totals depend on how many sets you logged.','note')})}
async function showWorkout(id){const dialog=$('workoutDialog'),body=$('workoutBody');body.replaceChildren();$('workoutTitle').textContent='Workout details';text(body,'p','Loading…');if(!dialog.open)dialog.showModal();try{const r=await fetch('/api/workout?id='+encodeURIComponent(id));if(!r.ok)throw Error('Unable to load this workout');const w=await r.json();body.replaceChildren();$('workoutTitle').textContent=w.title;text(body,'p',new Date(w.start_time).toLocaleString());const prior=(data?.recent||[]).filter(x=>x.title===w.title&&x.id!==w.id&&new Date(x.date)<new Date(w.start_time)).sort((a,b)=>new Date(b.date)-new Date(a.date))[0];if(prior){const comparison=text(body,'div','','workout-previous');text(comparison,'h3','Previous matching routine');text(comparison,'p',new Date(prior.date).toLocaleDateString()+' · '+prior.title);const current=(data.recent||[]).find(x=>x.id===w.id);if(current&&Number.isFinite(Number(current.minutes))&&Number.isFinite(Number(prior.minutes))){const delta=Number(current.minutes)-Number(prior.minutes);text(comparison,'p','Recorded duration: '+num(current.minutes)+' min vs '+num(prior.minutes)+' min ('+(delta>0?'+':'')+num(delta)+' min)')}if(current&&Number.isFinite(Number(current.exercises))&&Number.isFinite(Number(prior.exercises))){text(comparison,'p','Recorded exercises: '+num(current.exercises)+' vs '+num(prior.exercises))}const link=text(comparison,'button','View previous workout','detailbutton');link.onclick=()=>showWorkout(prior.id);text(comparison,'small','Comparison based on the recent workout list; no missing totals are estimated.','note')}w.exercises.forEach(e=>{const section=text(body,'section','','detailExercise');text(section,'h3',e.title);if(e.notes)text(section,'p',e.notes);const wrap=text(section,'div','','scroll'),table=text(wrap,'table',''),head=text(table,'thead',''),hr=text(head,'tr','');['Set','Type','kg','Reps','Time (s)','Distance (m)'].forEach(v=>text(hr,'th',v));const tbody=text(table,'tbody','');e.sets.forEach((set,i)=>{const tr=text(tbody,'tr','');[i+1,set.type||'normal',set.weight_kg??'—',set.reps??'—',set.duration_seconds??'—',set.distance_meters??'—'].forEach(v=>text(tr,'td',v))})})}catch(e){body.replaceChildren();text(body,'p',e.message)}}
$('closeWorkout').onclick=()=>$('workoutDialog').close();$('workoutDialog').addEventListener('click',ev=>{if(ev.target===$('workoutDialog')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});

let customApplied=false;
function statsURL(){if($('range').value==='custom'&&customApplied)return '/api/stats?days=90&start='+encodeURIComponent($('startDate').value)+'&end='+encodeURIComponent($('endDate').value);return '/api/stats?days='+($('range').value==='custom'?savedSettings.range:$('range').value)}
async function saveSettings(value){try{const r=await fetch('/api/settings',{method:'POST',headers:{'X-Hevy-Dashboard':'1','Content-Type':'application/json'},body:JSON.stringify(value)});if(!r.ok)throw Error('Could not save settings');savedSettings=await r.json();return true}catch(e){$('status').textContent=e.message;return false}}
async function initializeDashboard(){try{const r=await fetch('/api/settings');if(!r.ok)throw Error();savedSettings=await r.json();$('range').value=String(savedSettings.range)}catch{$('status').textContent='Unable to load saved settings.'}const now=new Date(),from=new Date(now);from.setDate(from.getDate()-89);const iso=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');$('startDate').value=iso(from);$('endDate').value=uiState.endDate||iso(now);$('startDate').value=uiState.startDate||$('startDate').value;$('favoritesOnly').checked=Boolean(uiState.favoritesOnly);$('exerciseSearch').value=uiState.exerciseSearch||'';load()}
$('customDates').onsubmit=ev=>{ev.preventDefault();if($('startDate').value>$('endDate').value){$('status').textContent='Start date must be before the end date.';return}customApplied=true;uiState.startDate=$('startDate').value;uiState.endDate=$('endDate').value;rememberUI();load()};
function routineEquivalent(kg){const refs=[['a grand piano',300],['a polar bear',450],['a small car',1200],['a giraffe',900],['a rhinoceros',2300],['an elephant',5000],['a helicopter',6000],['a city bus',12000],['a fire truck',18000],['a blue whale',120000]];if(!kg||kg<150)return null;let best=refs[0];for(const r of refs)if(Math.abs(Math.log(kg/r[1]))<Math.abs(Math.log(kg/best[1])))best=r;const n=kg/best[1];return (n>=1.5?num(n)+' × ':'')+best[0]}
function renderDataChecks(){const q=data.quality,box=$('qualityChecks');box.replaceChildren();if(!q)return;text(box,'p',q.checked+' stored records checked · '+q.duplicates+' exact duplicates deduplicated for analytics · '+q.excluded+' invalid records excluded from analytics');if(!q.flagged)text(box,'p','No duration, empty-workout or future-date flags.');q.issues.forEach(w=>{const line=text(box,'div','','session'),left=text(line,'div','');text(left,'strong',w.title+' · '+w.date);text(left,'p',w.reasons.join(' · '));const view=text(line,'button','Review','detailbutton');view.onclick=()=>showWorkout(w.id)})}
function renderSameWeight(){const box=$('sameWeight');box.replaceChildren();if(!data.same_weight?.length)text(box,'p','Train the same exercise at the same weight in two sessions to see rep progress.');(data.same_weight||[]).slice(0,12).forEach(e=>{const card=text(box,'div','','progresscard');text(card,'small',e.name);text(card,'h3',num(e.weight)+' kg');text(card,'strong',num(e.first_reps)+' → '+num(e.latest_reps)+' reps');text(card,'p',e.first_date+' → '+e.latest_date);text(card,'span',(e.change>0?'+':'')+num(e.change)+' reps','trend '+(e.change>0?'up':e.change<0?'down':'flat'))})}
function chartTarget(ev){return ev.target.closest?.('.barcol[title],#progress svg circle,#progress svg polyline')}
function showChartTooltip(ev){const target=chartTarget(ev);if(!target)return;const tip=$('chartTooltip'),message=target.getAttribute('title')||target.querySelector('title')?.textContent;if(!message)return;tip.textContent=message;tip.hidden=false;const rect=target.getBoundingClientRect(),x=ev.clientX||rect.left,y=ev.clientY||rect.top;tip.style.left=Math.max(8,Math.min(window.innerWidth-tip.offsetWidth-8,x+12))+'px';tip.style.top=Math.max(8,Math.min(window.innerHeight-tip.offsetHeight-8,y+12))+'px'}
document.addEventListener('pointerover',showChartTooltip);document.addEventListener('focusin',showChartTooltip);document.addEventListener('click',ev=>{if(chartTarget(ev))showChartTooltip(ev);else $('chartTooltip').hidden=true});document.addEventListener('pointerout',ev=>{if(chartTarget(ev))$('chartTooltip').hidden=true});document.addEventListener('focusout',()=>$('chartTooltip').hidden=true);window.addEventListener('scroll',()=>$('chartTooltip').hidden=true,true);

